import{_ as n,a0 as r,w as p,s as o,ao as d,I as e,x as s,a1 as i,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"在 Linux 上使用 tarball | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上使用 tarball | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上使用 tarball | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上使用 tarball | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20181217 Working with tarballs on Linux","title":"在 Linux 上使用 tarball","tag":"201901","desc":""},"relativePath":"201901/20181217 Working with tarballs on Linux.md","filePath":"[post].md"}'),h={name:"201901/20181217 Working with tarballs on Linux.md"};function g(b,a,k,u,c,f){const t=r("Link");return p(),o("div",null,[a[15]||(a[15]=d(`<h1 id="在-linux-上使用-tarball" tabindex="-1">在 Linux 上使用 tarball <a class="header-anchor" href="#在-linux-上使用-tarball" aria-label="Permalink to “在 Linux 上使用 tarball”">​</a></h1><blockquote><p>Tarball 提供了一种在 Linux 系统上备份和管理一组文件的通用方法。请按照以下提示了解如何创建它们，以及从中提取和删除单个文件。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2018/12/tarball-100783148-large.jpg" alt=""></p><p>“tarball” （LCTT 译注：国内也常称为“tar 包”）一词通常用于描述备份一组选择的文件并将它们打包在一个文件中的一种文件格式。该名称来自 .tar 文件扩展名和 <code>tar</code> 命令，它用于将文件打包到一个文件中，有时还会压缩该文件，使其在移动到其它系统时更小。</p><p>tarball 通常用于备份个人或系统文件来创建存档，特别是在进行可能需要撤消的更改之前。例如，Linux 系统管理员通常会在更改应用之前创建包含一系列配置文件的 tarball，以防必须撤消这些更改。从 tarball 中解压文件通常比在备份中搜索文件快。</p><h3 id="如何在-linux-上创建-tarball" tabindex="-1">如何在 Linux 上创建 tarball <a class="header-anchor" href="#如何在-linux-上创建-tarball" aria-label="Permalink to “如何在 Linux 上创建 tarball”">​</a></h3><p>使用如下命令，你可以在单条命令中创建 tarball 并压缩它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar -cvzf PDFs.tar.gz *.pdf</span></span></code></pre></div><p>其结果是一个压缩文件（gzip 压缩的），其中包含了当前目录中的所有 PDF 文件。当然，压缩是可选的。一个稍微简单的只是将 PDF 文件打包成未压缩 tarball 的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar -cvf PDFs.tar *.pdf</span></span></code></pre></div><p>注意，选项中的 <code>z</code> 将文件变成压缩的。 <code>c</code> 表明创建文件，<code>v</code>（详细）表示你在命令运行时需要一些反馈。如果你不想查看列出的文件，请忽略 <code>v</code>。</p><p>另一个常见的命名约定是给压缩的 tarball 命名成 .tgz 而不是双扩展名 .tar.gz，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar cvzf MyPDFs.tgz *.pdf</span></span></code></pre></div><h3 id="如何从-tarball-中解压文件" tabindex="-1">如何从 tarball 中解压文件 <a class="header-anchor" href="#如何从-tarball-中解压文件" aria-label="Permalink to “如何从 tarball 中解压文件”">​</a></h3><p>要从 gzip 压缩包中解压所有文件，你可以使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar -xvzf file.tar.gz</span></span></code></pre></div><p>如果使用 .tgz 命名约定，该命令将如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar -xvzf MyPDFs.tgz</span></span></code></pre></div><p>要从 gzip 包中解压单个文件，你可以执行几乎相同的操作，只需添加文件名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar -xvzf PDFs.tar.gz ShenTix.pdf</span></span>
<span class="line"><span>ShenTix.pdf</span></span>
<span class="line"><span>ls -l ShenTix.pdf</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 122057 Dec 14 14:43 ShenTix.pdf</span></span></code></pre></div><p>如果未压缩 tarball，你甚至可以从 tarball 中删除文件。例如，如果我们想从 PDFs.tar.gz 中删除我们上面解压过的文件，我们会这样做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gunzip PDFs.tar.gz</span></span>
<span class="line"><span>$ ls -l PDFs.tar</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 10700800 Dec 15 11:51 PDFs.tar</span></span>
<span class="line"><span>$ tar -vf PDFs.tar --delete ShenTix.pdf</span></span>
<span class="line"><span>$ ls -l PDFs.tar</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 10577920 Dec 15 11:45 PDFs.tar</span></span></code></pre></div><p>请注意，我们在删除 ShenTix.pdf 后，缩小了一点 tarball 文件占用的空间。如果我们想要，我们可以再次压缩文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gzip -f PDFs.tar</span></span>
<span class="line"><span>ls -l PDFs.tar.gz</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 10134499 Dec 15 11:51 PDFs.tar.gzFlickr / James St. John</span></span></code></pre></div><p>丰富的命令行选项使得 tarball 使用起来简单方便。</p><hr>`,26)),e("p",null,[a[1]||(a[1]=s("via: ",-1)),i(t,{href:"https://www.networkworld.com/article/3328840/linux/working-with-tarballs-on-linux.html"},{default:l(()=>[...a[0]||(a[0]=[s("https://www.networkworld.com/article/3328840/linux/working-with-tarballs-on-linux.html",-1)])]),_:1})]),e("p",null,[a[6]||(a[6]=s("作者：",-1)),i(t,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:l(()=>[...a[2]||(a[2]=[s("Sandra Henry-Stocker",-1)])]),_:1}),a[7]||(a[7]=s(" 选题：",-1)),i(t,{href:"https://github.com/lujun9972"},{default:l(()=>[...a[3]||(a[3]=[s("lujun9972",-1)])]),_:1}),a[8]||(a[8]=s(" 译者：",-1)),i(t,{href:"https://github.com/geekpi"},{default:l(()=>[...a[4]||(a[4]=[s("geekpi",-1)])]),_:1}),a[9]||(a[9]=s(" 校对：",-1)),i(t,{href:"https://github.com/wxy"},{default:l(()=>[...a[5]||(a[5]=[s("wxy",-1)])]),_:1})]),e("p",null,[a[12]||(a[12]=s("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...a[10]||(a[10]=[s("LCTT",-1)])]),_:1}),a[13]||(a[13]=s(" 原创编译，",-1)),i(t,{href:"https://linux.cn/"},{default:l(()=>[...a[11]||(a[11]=[s("Linux中国",-1)])]),_:1}),a[14]||(a[14]=s(" 荣誉推出",-1))])])}const C=n(h,[["render",g]]);export{w as __pageData,C as default};
